<?php
require_once __DIR__.'/bootstrap.php';
$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));
foreach([$from,$to] as $d){if($d!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d)||!DateTime::createFromFormat('!Y-m-d',$d)||DateTime::createFromFormat('!Y-m-d',$d)->format('Y-m-d')!==$d)){$from='';$to='';break;}}
$conditions=[];$params=[];
if($from!==''){$conditions[]='s.sale_date >= ?';$params[]=$from.' 00:00:00';}
if($to!==''){$conditions[]='s.sale_date < DATE_ADD(?,INTERVAL 1 DAY)';$params[]=$to;}
$where=$conditions?'WHERE '.implode(' AND ',$conditions):'';
$salesByProduct=rows('SELECT p.product_name,p.sku,c.category_name,SUM(si.quantity) total_units,SUM(si.quantity*si.unit_price) revenue FROM sale_items si JOIN sales s ON s.sale_id=si.sale_id JOIN products p ON p.product_id=si.product_id JOIN categories c ON c.category_id=p.category_id '.$where.' GROUP BY p.product_id,p.product_name,p.sku,c.category_name ORDER BY revenue DESC',$params);
$salesSummary=one('SELECT COUNT(DISTINCT s.sale_id) transaction_count,COALESCE(SUM(si.quantity),0) units,COALESCE(SUM(si.quantity*si.unit_price),0) revenue FROM sales s LEFT JOIN sale_items si ON si.sale_id=s.sale_id '.$where,$params);
$stock=rows('SELECT p.product_name,p.sku,c.category_name,p.stock_quantity,p.reorder_level, GREATEST(p.reorder_level-p.stock_quantity,0) shortage,p.selling_price FROM products p JOIN categories c ON c.category_id=p.category_id WHERE p.stock_quantity<=p.reorder_level ORDER BY (p.reorder_level-p.stock_quantity) DESC,p.stock_quantity ASC');
$inventory=one('SELECT COUNT(*) products,COALESCE(SUM(stock_quantity),0) units,COALESCE(SUM(stock_quantity*selling_price),0) value FROM products');
render_header('Reports','reports.php');page_heading('ANALYTICS','Reports','Measure sales performance and identify replenishment needs.','<button class="btn secondary no-print" onclick="window.print()">'.icon('printer').' Print report</button>');
?>


<div class="report-heading"><div><h2>Sales performance</h2><p>Revenue and units sold by product. Filter by transaction date.</p></div><form method="get" class="date-filter"><div class="field"><label>From</label><input type="date" name="from" value="<?=e($from)?>"></div><div class="field"><label>To</label><input type="date" name="to" value="<?=e($to)?>"></div><button class="btn secondary" type="submit">Apply</button><a class="btn ghost" href="reports.php">Reset</a></form></div>
<div class="stats-grid report-stats"><div class="stat-card"><div class="stat-top"><span>Sales revenue</span><span class="stat-symbol purple"><?=icon('chart')?></span></div><strong><?=cash($salesSummary['revenue'])?></strong><small>Selected reporting period</small></div><div class="stat-card"><div class="stat-top"><span>Transactions</span><span class="stat-symbol green"><?=icon('cart')?></span></div><strong><?=number_format($salesSummary['transaction_count'])?></strong><small>Completed sales</small></div><div class="stat-card"><div class="stat-top"><span>Units sold</span><span class="stat-symbol blue"><?=icon('box')?></span></div><strong><?=number_format($salesSummary['units'])?></strong><small>Quantity sold across all products</small></div><div class="stat-card"><div class="stat-top"><span>Low-stock products</span><span class="stat-symbol orange"><?=icon('alert')?></span></div><strong><?=count($stock)?></strong><small>Need restocking attention</small></div></div>
<section class="panel"><div class="panel-head"><div><h3>Product sales report</h3><p>Revenue by product with quantities sold</p></div><span class="report-label">SALES ANALYSIS</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th class="right">Units sold</th><th class="right">Revenue (LKR)</th></tr></thead><tbody><?php foreach($salesByProduct as $r):?><tr><td><strong><?=e($r['product_name'])?></strong><small class="table-sub"><?=e($r['sku'])?></small></td><td><?=e($r['category_name'])?></td><td class="right"><?=e($r['total_units'])?></td><td class="right amount"><?=cash($r['revenue'])?></td></tr><?php endforeach;if(!$salesByProduct):?><tr><td class="empty" colspan="4">No sales during this period.</td></tr><?php endif;?><tr class="total-row"><td colspan="2">TOTAL</td><td class="right"><?=e($salesSummary['units'])?></td><td class="right"><?=cash($salesSummary['revenue'])?></td></tr></tbody></table></div></section>


<div class="report-heading" id="stock-report"><div><h2>Inventory health</h2><p>Current stock position and products requiring replenishment.</p></div><div class="inventory-summary">Total inventory: <strong><?=e($inventory['units'])?> units</strong> · <?=cash($inventory['value'])?> retail value</div></div>
<section class="panel"><div class="panel-head"><div><h3>Low stock report</h3><p>Products with stock at or below reorder level</p></div><span class="report-label warning">RESTOCK ALERT</span></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th class="right">Current stock</th><th class="right">Reorder level</th><th class="right">Shortfall</th><th>Status</th></tr></thead><tbody><?php foreach($stock as $r):?><tr><td><strong><?=e($r['product_name'])?></strong><small class="table-sub"><?=e($r['sku'])?></small></td><td><?=e($r['category_name'])?></td><td class="right"><?=e($r['stock_quantity'])?></td><td class="right"><?=e($r['reorder_level'])?></td><td class="right amount"><?=e($r['shortage'])?></td><td><span class="pill danger">Reorder</span></td></tr><?php endforeach;if(!$stock):?><tr><td colspan="6" class="empty">Great! No products are below their reorder threshold.</td></tr><?php endif;?></tbody></table></div></section>
<?php render_footer(); ?>
